inputs = ['ayu', 'kejkh', 'bfej', 'havxgu', 'ezbeev']
outputs = ['aiyu', 'kevxaevkx', 'bfevxaev', 'xavxgu', 'eaevbeev']

print("Input -> Output:")
for i in range(len(inputs)):
    print(f"{inputs[i]} -> {outputs[i]}")

# Analyze each transformation:
print("\nDetailed analysis:")
for i in range(len(inputs)):
    inp, outp = inputs[i], outputs[i]
    print(f"Input: '{inp}' -> Output: '{outp}'")

    # Find differences
    if len(inp) != len(outp):
        print(f"  Length changed: {len(inp)} -> {len(outp)}")

    # Look for patterns
    if inp == 'ayu' and outp == 'aiyu':
        print("  Add 'i' at beginning")
    elif inp == 'kejkh' and outp == 'kevxaevkx':
        print("  Complex transformation with multiple replacements")
    elif inp == 'bfej' and outp == 'bfevxaev':
        print("  Insert 'vxaev' in middle")
    elif inp == 'havxgu' and outp == 'xavxgu':
        print("  Replace 'h' with 'x'")
    elif inp == 'ezbeev' and outp == 'eaevbeev':
        print("  Insert 'aev' after 'e'")

